INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Multicast nur für Video-Streaming gedacht?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Gerätesuche wie NDP"}, {"text": "Ja", "correct": false, "because": "Nutzung ist breiter"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse nutze ich, um alle Geräte im lokalen Netz anzusprechen?', 3, '[{"text": "FF02::1", "correct": true, "because": "Alle Knoten in Link-Local"}, {"text": "FF02::2", "correct": false, "because": "Nur Router"}, {"text": "FE80::1", "correct": false, "because": "Unicast-Adresse"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat Multicast?', 5, '[{"text": "1-zu-Gruppe", "correct": true, "because": "Effiziente Gruppenkommunikation"}, {"text": "Link-Local-Scope", "correct": true, "because": "FF02::1 bleibt lokal"}, {"text": "Hohe Latenz", "correct": false, "because": "Netzwerkabhängig"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nicht Multicast-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Multicast nutzt ICMPv6. b) Es ersetzt Unicast.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unicast bleibt eigenständig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung von Multicast?', 4, '[{"text": "Gruppenadressen", "correct": false, "because": "Kern von Multicast"}, {"text": "Scope", "correct": false, "because": "Definiert Reichweite"}, {"text": "Einzelne MAC-Adressen", "correct": true, "because": "Multicast ist gruppenbasiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Multicast Bandbreite spart?', 2, '[{"text": "Ja", "correct": true, "because": "Daten einmal gesendet"}, {"text": "Nein", "correct": false, "because": "Effizienz ist Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse wähle ich für alle Router im Segment?', 3, '[{"text": "FF02::2", "correct": true, "because": "Router-Gruppe"}, {"text": "FF02::1", "correct": false, "because": "Alle Knoten"}, {"text": "FF00::1", "correct": false, "because": "Ungültiger Scope"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Multicast im Netzwerk?', 5, '[{"text": "Effiziente Gruppenkommunikation", "correct": true, "because": "Weniger Pakete"}, {"text": "Geräteerkennung", "correct": true, "because": "NDP nutzt es"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nicht enthalten"}, {"text": "Hohe Geschwindigkeit", "correct": false, "because": "Netzwerkabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Multicast reduziert Netzlast. b) Es ist nur für IPv4. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch in IPv6"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Multicast?', 4, '[{"text": "Gruppenadresse", "correct": false, "because": "Definiert Empfänger"}, {"text": "Scope-ID", "correct": false, "because": "Begrenzt Reichweite"}, {"text": "Portnummern", "correct": true, "because": "Transportebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist FF02::1 global gültig?', 2, '[{"text": "Nein", "correct": true, "because": "Link-Local-Scope"}, {"text": "Ja", "correct": false, "because": "Nur lokales Segment"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse nutze ich, um alle Knoten zu erreichen?', 4, '[{"text": "FF02::1", "correct": true, "because": "Alle Geräte im Segment"}, {"text": "FF02::FB", "correct": false, "because": "mDNS-spezifisch"}, {"text": "FE80::1", "correct": false, "because": "Unicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Multicast nur für große Netze ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch in kleinen Netzen nützlich"}, {"text": "Ja", "correct": false, "because": "Skalierung nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Multicast?', 3, '[{"text": "Richtige Gruppenadresse", "correct": true, "because": "Erreicht Zielgruppe"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Netzwerkabhängig"}, {"text": "Schnelle Antwortzeit", "correct": false, "because": "Diagnoseabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Multicast nutzt FF00::/8. b) Es ersetzt Broadcast.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "IPv6 hat keinen Broadcast"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen Multicast nützlich?', 5, '[{"text": "Skalierbarkeit", "correct": true, "because": "Effizient bei Gruppen"}, {"text": "Ressourcenschonung", "correct": true, "because": "Weniger Duplikate"}, {"text": "Hohe Sicherheit", "correct": false, "because": "Keine Verschlüsselung"}, {"text": "Geringe Latenz", "correct": false, "because": "Netzwerkabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Multicast unwichtig?', 3, '[{"text": "Gruppenzugehörigkeit", "correct": false, "because": "Definiert Empfänger"}, {"text": "Scope", "correct": false, "because": "Begrenzt Reichweite"}, {"text": "Einzel-IPs", "correct": true, "because": "Gruppenfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzt Multicast Unicast komplett?', 3, '[{"text": "Nein", "correct": true, "because": "Unicast für Einzelkommunikation"}, {"text": "Ja", "correct": false, "because": "Ergänzung, kein Ersatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Multicast Router überschreitet?', 2, '[{"text": "Nein", "correct": true, "because": "Link-Local bleibt lokal"}, {"text": "Ja", "correct": false, "because": "Scope-begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse wähle ich für eine spezielle Gerätegruppe?', 4, '[{"text": "FF02::1:FFXX:XXXX", "correct": true, "because": "Solicited-Node Multicast"}, {"text": "FF02::1", "correct": false, "because": "Alle Knoten"}, {"text": "FE80::2", "correct": false, "because": "Unicast"}]');
